scwin.vScrenID = "ULDINS25300.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_2);
    var array_grid = [grd_List];
    setResizeGrid(array_grid, 300);

    // 콤보 세팅.
    scwin.fn_SetCombo();

    // 기본값 세팅
    scwin.fn_SetDefaultVal();

    //최대수익액, 최대손실액, 발행가액 없앤다 2013.12.5
    $c.stf.showObj(chb_MAX_EARNG_VAL, false);
    $c.stf.showObj(chb_MAX_LOSS_VAL, false);
    $c.stf.showObj(chb_BND_ISU_PRC, false);
};



/**
 *  콤보박스 만들기
 */
scwin.fn_SetCombo = function() {
    //ins_combo_set(dts_LIST_STAT_CD, vScrenID, SCREN_PROCS_TP_CD_01 ,"00714","ALL"); //상장상태코드 		

};

/**
 *  화면의 기본값 세팅
 */
scwin.fn_SetDefaultVal = function() {
    var sToday = $c.ut.cGetToday2();
    edt_FROM_ISU_DD.setValue($c.ut.cGetPlusDate2($c.ut.cGetMinusYear(sToday, 1), 1));
    edt_TO_ISU_DD.setValue(sToday);
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_List.removeAll();
};


/**
 * 주권조회
 */
scwin.ins_search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_List);

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20210528
    btn_search.setDisabled(true);
    btn_search.src = "../img/btn_select_d.gif";
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.down.select.listStdCdBndElsDlsDownLoadInquiry" + "&outputMessageId=INS_LIST_STDCD_BND_ELSDLS_DOWNLOAD_INQUIRY" + "&{P}ACTIV_TP_CD=" + $c.stf.getObjectValue(cmb_ACTIV_TP_CD) + "&{P}ISUR_CD_FROM=" + $c.stf.getObjectValue(txb_FROM_ISUR_CD) + "&{P}ISUR_CD_TO=" + $c.stf.getObjectValue(txb_TO_ISUR_CD) + "&{P}ISU_DD_FROM=" + $c.stf.getObjectValue(edt_FROM_ISU_DD) + "&{P}ISU_DD_TO=" + $c.stf.getObjectValue(edt_TO_ISU_DD) + "&{P}STD_CD_GRNT_DD_FROM=" + $c.stf.getObjectValue(edt_FROM_STD_CD_GRNT_DD) + "&{P}STD_CD_GRNT_DD_TO=" + $c.stf.getObjectValue(edt_TO_STD_CD_GRNT_DD);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};


/**
 * 사전체크
 */
scwin.fn_ChkValid = function() {
    // 발행기관코드 체크
    if ($c.stf.getObjectValue(txb_FROM_ISUR_CD) > $c.stf.getObjectValue(txb_TO_ISUR_CD)) {
        $c.win.alert("검색시작 발행기관코드가 종료 발행기관코드보다 큽니다.");
        txb_FROM_ISUR_CD.focus();
        return false;
    }
    // 발행일 체크
    if ($c.stf.compareFromToDate2(edt_FROM_ISU_DD, edt_TO_ISU_DD) == false) {
        return false;
    }
    // 코드부여일 체크
    if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_GRNT_DD, edt_TO_STD_CD_GRNT_DD) == false) {
        return false;
    }
    // 발행일
    if (($c.stf.getObjectValue(edt_FROM_ISU_DD) != "" && $c.stf.getObjectValue(edt_TO_ISU_DD) != "") &&
        eval($c.ut.cGetPlusYear(edt_FROM_ISU_DD.getValue(), 1)) < eval(edt_TO_ISU_DD.getValue())) {
        //alert("발행일의 검색 기간은 1년 이내로만 가능합니다.");

        //edt_FROM_ISU_DD.Focus();

        //return false;

    }
    // 코드부여일
    if (($c.stf.getObjectValue(edt_FROM_STD_CD_GRNT_DD) != "" && $c.stf.getObjectValue(edt_TO_STD_CD_GRNT_DD) != "") &&
        eval($c.ut.cGetPlusYear(edt_FROM_STD_CD_GRNT_DD.getValue(), 1)) < eval(edt_TO_STD_CD_GRNT_DD.getValue())) {
        //alert("코드부여일의 검색 기간은 1년 이내로만 가능합니다.");

        //edt_FROM_STD_CD_GRNT_DD.Focus();

        //return false;

    }
    return true;
};


/**
 * 체크박스 체크 시 그리드 항목 show
 */
scwin.fn_GridCtrl = function(pObj) {
    var sColId = pObj.id;
    sColId = sColId.replace("chb_", "");
    var bChecked = $c.stf.getObjectValue(pObj);
    if (bChecked == "Y" && $c.cm.getColumnProp(grd_List, sColId, "Show") != "TRUE") {
        $c.cm.setColumnProp(grd_List, sColId, "Show", true);
    } else if (bChecked == "N" && $c.cm.getColumnProp(grd_List, sColId, "Show") == "TRUE") {
        $c.cm.setColumnProp(grd_List, sColId, "Show", false);
    }
    //grd_List.AutoResizeAllCol(true);

};




/**
 * 전체선택 체크 시 나머지 모두 언체크.
 */
scwin.fn_AllUnCheck = function() {
    var sAllChecked = $c.stf.getObjectValue(chb_ALL);
    var oCheckBoxs = document.getElementsByName("chk");
    for (var nRow = 0; nRow < oCheckBoxs.length; nRow++) {
        oCheckBoxs[nRow].setValue((sAllChecked == "Y") ? true : false);
        scwin.fn_GridCtrl(oCheckBoxs[nRow]);
    }
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.dts_List_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_List);
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_List);

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20210528
    btn_search.setDisabled(false);
    btn_search.src = "../img/btn_select.gif";
};
scwin.btn_Excel_onclick = function() {
    if (dts_List.getTotalRow() <= 0) {
        $c.win.alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 로그 남기고..

    var today = $c.ut.cGetToday("yyyymmddhhmmss");
    var title = "ELSDLS다운로드";
    var xls_path = $c.session.getExcelDownPath() + today + "_" + title + ".xls";
    $c.data.downloadGridViewOffice(grd_List, title, xls_path, 8, 0);
    //grd_List.GridToExcel(title, "", "8");

};
